func (t TableStreet) IS() *IS {
	return NewIS(string(t))
}

func (t TableStreet) ID() *ID {
	return NewID(string(t))
}

func (t TableStreet) ST() *ST {
	return NewST(string(t))
}

func (t TableStreet) CWE() *CWE {
	return NewCWE().SetIdentifier(string(t)).SetText(t.Description())
}

func (t TableStreet) CNE() *CNE {
	return NewCNE().SetIdentifier(string(t)).SetText(t.Description())
}

